#!/usr/bin/env python3
"""
A minimal Lua/LuaJIT interpreter implementation in Python
Written from scratch to reproduce LuaJIT behavior
"""

import sys
import re
import math
import operator
from io import StringIO

# Version information to match LuaJIT
LUAJIT_VERSION = "LuaJIT 2.1.1772570160"
LUA_VERSION = "Lua 5.1"

class LuaException(Exception):
    """Base exception for Lua errors"""
    pass

class ParseError(LuaException):
    """Raised when parsing Lua code fails"""
    pass

class RuntimeError(LuaException):
    """Raised during Lua execution"""
    pass

class Token:
    """Represents a Lua token"""
    def __init__(self, type, value, line=1, col=1):
        self.type = type
        self.value = value
        self.line = line
        self.col = col

    def __repr__(self):
        return f"Token({self.type}, {self.value!r})"

class Lexer:
    """Lua lexical analyzer"""

    TOKEN_PATTERNS = [
        ('COMMENT', r'--.*$'),
        ('MULTICOMMENT', r'--\[\[.*?\]\]'),
        ('STRING', r'"(?:\\.|[^"\\])*"'),
        ('STRING', r"'(?:\\.|[^'\\])*'"),
        ('NUMBER', r'\d+\.\d+'),
        ('NUMBER', r'0x[0-9a-fA-F]+'),
        ('NUMBER', r'\d+'),
        ('KEYWORD', r'\b(and|or|not|if|then|else|elseif|end|for|do|while|function|local|return|in|break|nil|true|false)\b'),
        ('IDENT', r'[a-zA-Z_][a-zA-Z0-9_]*'),
        ('OP', r'(\.\.|\^|~|<<|>>|<=|>=|==|~=|\.\.\.|\+|-|\*|/|%|&|\||\^|<|>|=|~|\(|\)|\[|\]|\{|\}|,|;|\.|--)'),
        ('WHITESPACE', r'\s+'),
    ]

    def __init__(self, code):
        self.code = code
        self.tokens = []
        self.pos = 0
        self.line = 1
        self.col = 1

    def tokenize(self):
        """Tokenize the input code"""
        lines = self.code.split('\n')
        for line_no, line in enumerate(lines, 1):
            pos = 0
            while pos < len(line):
                # Skip whitespace
                if line[pos].isspace():
                    pos += 1
                    continue

                # Try to match tokens
                matched = False
                for pattern_type, pattern in self.TOKEN_PATTERNS:
                    regex = re.compile(pattern)
                    match = regex.match(line, pos)
                    if match:
                        value = match.group(0)
                        if pattern_type != 'WHITESPACE' and pattern_type != 'COMMENT':
                            self.tokens.append(Token(pattern_type, value, line_no, pos+1))
                        pos = match.end()
                        matched = True
                        break

                if not matched:
                    raise ParseError(f"Unexpected character '{line[pos]}' at line {line_no}, col {pos+1}")

        return self.tokens

class Parser:
    """Lua parser"""

    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def current(self):
        """Get current token"""
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def peek(self, offset=1):
        """Peek ahead"""
        if self.pos + offset < len(self.tokens):
            return self.tokens[self.pos + offset]
        return None

    def consume(self, expected_type=None):
        """Consume and return current token"""
        token = self.current()
        if expected_type and token and token.type != expected_type:
            raise ParseError(f"Expected {expected_type}, got {token.type}")
        self.pos += 1
        return token

    def parse(self):
        """Parse tokens into an AST"""
        statements = []
        while self.current():
            stmt = self.parse_statement()
            if stmt:
                statements.append(stmt)
        return statements

    def parse_statement(self):
        """Parse a single statement"""
        token = self.current()
        if not token:
            return None

        if token.type == 'KEYWORD':
            if token.value == 'if':
                return self.parse_if()
            elif token.value == 'for':
                return self.parse_for()
            elif token.value == 'while':
                return self.parse_while()
            elif token.value == 'function':
                return self.parse_function_def()
            elif token.value == 'local':
                return self.parse_local()
            elif token.value == 'return':
                return self.parse_return()
            elif token.value == 'break':
                self.consume()
                return ('break',)

        # Try to parse assignment or expression
        expr = self.parse_expr()

        # Check for assignment
        if self.current() and self.current().value == '=':
            self.consume()  # consume '='
            value = self.parse_expr()
            return ('assign', expr, value)

        # It's just an expression statement
        if expr:
            return ('expr_stmt', expr)

        return None

    def parse_if(self):
        """Parse if statement"""
        self.consume('KEYWORD')  # consume 'if'
        cond = self.parse_expr()
        self.consume('KEYWORD')  # consume 'then'
        then_body = []
        while self.current() and not (self.current().type == 'KEYWORD' and self.current().value in ('else', 'elseif', 'end')):
            stmt = self.parse_statement()
            if stmt:
                then_body.append(stmt)

        else_body = []
        if self.current() and self.current().type == 'KEYWORD' and self.current().value == 'else':
            self.consume()
            while self.current() and not (self.current().type == 'KEYWORD' and self.current().value == 'end'):
                stmt = self.parse_statement()
                if stmt:
                    else_body.append(stmt)

        self.consume('KEYWORD')  # consume 'end'
        return ('if', cond, then_body, else_body)

    def parse_for(self):
        """Parse for loop"""
        self.consume('KEYWORD')  # consume 'for'
        var = self.consume('IDENT')
        self.consume('OP')  # consume '='
        start = self.parse_expr()
        self.consume('OP')  # consume ','
        end = self.parse_expr()

        step = None
        if self.current() and self.current().value == ',':
            self.consume()
            step = self.parse_expr()

        self.consume('KEYWORD')  # consume 'do'
        body = []
        while self.current() and not (self.current().type == 'KEYWORD' and self.current().value == 'end'):
            stmt = self.parse_statement()
            if stmt:
                body.append(stmt)

        self.consume('KEYWORD')  # consume 'end'
        return ('for', var.value, start, end, step, body)

    def parse_while(self):
        """Parse while loop"""
        self.consume('KEYWORD')  # consume 'while'
        cond = self.parse_expr()
        self.consume('KEYWORD')  # consume 'do'
        body = []
        while self.current() and not (self.current().type == 'KEYWORD' and self.current().value == 'end'):
            stmt = self.parse_statement()
            if stmt:
                body.append(stmt)

        self.consume('KEYWORD')  # consume 'end'
        return ('while', cond, body)

    def parse_function_def(self):
        """Parse function definition"""
        self.consume('KEYWORD')  # consume 'function'
        name = self.consume('IDENT').value if self.current().type == 'IDENT' else None
        self.consume('OP')  # consume '('
        params = []
        while self.current() and self.current().value != ')':
            params.append(self.consume('IDENT').value)
            if self.current() and self.current().value == ',':
                self.consume()
        self.consume('OP')  # consume ')'

        body = []
        while self.current() and not (self.current().type == 'KEYWORD' and self.current().value == 'end'):
            stmt = self.parse_statement()
            if stmt:
                body.append(stmt)

        self.consume('KEYWORD')  # consume 'end'
        return ('function_def', name, params, body)

    def parse_local(self):
        """Parse local variable declaration"""
        self.consume('KEYWORD')  # consume 'local'
        var = self.consume('IDENT').value

        value = None
        if self.current() and self.current().value == '=':
            self.consume()
            value = self.parse_expr()

        return ('local', var, value)

    def parse_return(self):
        """Parse return statement"""
        self.consume('KEYWORD')  # consume 'return'
        values = []
        if self.current() and not (self.current().type == 'KEYWORD' and self.current().value == 'end'):
            values.append(self.parse_expr())
            while self.current() and self.current().value == ',':
                self.consume()
                values.append(self.parse_expr())
        return ('return', values)

    def parse_expr(self):
        """Parse expression"""
        return self.parse_or()

    def parse_or(self):
        """Parse 'or' expression"""
        left = self.parse_and()
        while self.current() and self.current().value == 'or':
            self.consume()
            right = self.parse_and()
            left = ('or', left, right)
        return left

    def parse_and(self):
        """Parse 'and' expression"""
        left = self.parse_not()
        while self.current() and self.current().value == 'and':
            self.consume()
            right = self.parse_not()
            left = ('and', left, right)
        return left

    def parse_not(self):
        """Parse 'not' expression"""
        if self.current() and self.current().value == 'not':
            self.consume()
            expr = self.parse_not()
            return ('not', expr)
        return self.parse_comparison()

    def parse_comparison(self):
        """Parse comparison expression"""
        left = self.parse_concat()
        while self.current() and self.current().value in ('==', '~=', '<', '>', '<=', '>='):
            op = self.consume().value
            right = self.parse_concat()
            left = ('cmp', op, left, right)
        return left

    def parse_concat(self):
        """Parse concatenation expression"""
        left = self.parse_additive()
        while self.current() and self.current().value == '..':
            self.consume()
            right = self.parse_additive()
            left = ('concat', left, right)
        return left

    def parse_additive(self):
        """Parse addition/subtraction"""
        left = self.parse_multiplicative()
        while self.current() and self.current().value in ('+', '-'):
            op = self.consume().value
            right = self.parse_multiplicative()
            left = (op, left, right)
        return left

    def parse_multiplicative(self):
        """Parse multiplication/division"""
        left = self.parse_unary()
        while self.current() and self.current().value in ('*', '/', '%'):
            op = self.consume().value
            right = self.parse_unary()
            left = (op, left, right)
        return left

    def parse_unary(self):
        """Parse unary expression"""
        if self.current() and self.current().value in ('-', 'not', '#'):
            op = self.consume().value
            expr = self.parse_unary()
            return (op, expr)
        return self.parse_power()

    def parse_power(self):
        """Parse power expression"""
        left = self.parse_primary()
        if self.current() and self.current().value == '^':
            self.consume()
            right = self.parse_power()  # Right associative
            left = ('^', left, right)
        return left

    def parse_primary(self):
        """Parse primary expression"""
        token = self.current()

        if not token:
            return None

        # Literals
        if token.type == 'NUMBER':
            self.consume()
            value = float(token.value) if '.' in token.value else int(token.value)
            return ('number', value)

        if token.type == 'STRING':
            self.consume()
            # Remove quotes and process escape sequences
            s = token.value[1:-1]
            s = s.replace('\\n', '\n').replace('\\t', '\t').replace('\\"', '"').replace("\\'", "'")
            return ('string', s)

        if token.type == 'KEYWORD':
            if token.value == 'nil':
                self.consume()
                return ('nil',)
            elif token.value == 'true':
                self.consume()
                return ('bool', True)
            elif token.value == 'false':
                self.consume()
                return ('bool', False)
            elif token.value == 'function':
                return self.parse_function_expr()

        if token.type == 'IDENT':
            name = self.consume().value
            return self.parse_suffix(('var', name))

        if token.value == '(':
            self.consume()
            expr = self.parse_expr()
            self.consume('OP')  # consume ')'
            return self.parse_suffix(expr)

        if token.value == '{':
            return self.parse_table()

        return None

    def parse_suffix(self, expr):
        """Parse suffix operators (indexing, method calls, etc.)"""
        while True:
            token = self.current()
            if not token:
                break

            if token.value == '[':
                self.consume()
                index = self.parse_expr()
                self.consume('OP')  # consume ']'
                expr = ('index', expr, index)

            elif token.value == '.':
                self.consume()
                field = self.consume('IDENT').value
                expr = ('field', expr, field)

            elif token.value == '(':
                self.consume()
                args = []
                while self.current() and self.current().value != ')':
                    args.append(self.parse_expr())
                    if self.current() and self.current().value == ',':
                        self.consume()
                self.consume('OP')  # consume ')'
                expr = ('call', expr, args)

            elif token.type == 'STRING' or token.value == '{':
                # Implicit call with string or table argument
                if token.type == 'STRING':
                    arg = self.parse_primary()
                else:
                    arg = self.parse_table()
                expr = ('call', expr, [arg])

            else:
                break

        return expr

    def parse_function_expr(self):
        """Parse function expression (anonymous function)"""
        self.consume('KEYWORD')  # consume 'function'
        self.consume('OP')  # consume '('
        params = []
        while self.current() and self.current().value != ')':
            params.append(self.consume('IDENT').value)
            if self.current() and self.current().value == ',':
                self.consume()
        self.consume('OP')  # consume ')'

        body = []
        while self.current() and not (self.current().type == 'KEYWORD' and self.current().value == 'end'):
            stmt = self.parse_statement()
            if stmt:
                body.append(stmt)

        self.consume('KEYWORD')  # consume 'end'
        return ('function_expr', params, body)

    def parse_table(self):
        """Parse table literal"""
        self.consume('OP')  # consume '{'
        elements = []
        while self.current() and self.current().value != '}':
            if self.current().type == 'IDENT' and self.peek() and self.peek().value == '=':
                # Key-value pair
                key = self.consume().value
                self.consume()  # consume '='
                value = self.parse_expr()
                elements.append(('kvpair', key, value))
            else:
                # Array element
                value = self.parse_expr()
                elements.append(('arrayelem', value))

            if self.current() and self.current().value in (',', ';'):
                self.consume()

        self.consume('OP')  # consume '}'
        return ('table', elements)

class Interpreter:
    """Lua interpreter that executes AST"""

    def __init__(self, script_path=None, script_args=None):
        self.globals = {}
        self.locals_stack = [{}]
        self.script_path = script_path
        self.script_args = script_args or []
        self.setup_stdlib()
        self.return_value = None
        self.should_return = False
        self.should_break = False

    def setup_stdlib(self):
        """Setup standard library"""
        self.globals['print'] = self.builtin_print
        self.globals['type'] = self.builtin_type
        self.globals['tostring'] = self.builtin_tostring
        self.globals['tonumber'] = self.builtin_tonumber
        self.globals['assert'] = self.builtin_assert
        self.globals['_VERSION'] = LUA_VERSION

        # Create arg table
        arg_table = {}
        arg_table[0] = self.script_path
        for i, arg in enumerate(self.script_args, 1):
            arg_table[i] = arg
        self.globals['arg'] = arg_table

        # Math library
        self.globals['math'] = {
            'pi': math.pi,
            'e': math.e,
            'sin': math.sin,
            'cos': math.cos,
            'tan': math.tan,
            'floor': math.floor,
            'ceil': math.ceil,
            'sqrt': math.sqrt,
            'abs': abs,
            'max': max,
            'min': min,
            'deg': math.degrees,
            'rad': math.radians,
        }

        # String library
        self.globals['string'] = {
            'len': self.str_len,
            'upper': lambda s: str(s).upper(),
            'lower': lambda s: str(s).lower(),
            'sub': self.str_sub,
        }

        # Table library
        self.globals['table'] = {
            'insert': self.table_insert,
            'remove': self.table_remove,
        }

        # jit library for compatibility
        self.globals['jit'] = {
            'version': LUAJIT_VERSION,
        }

    def builtin_print(self, *args):
        """Built-in print function"""
        print(*[self.to_string(arg) for arg in args], sep='\t')
        return None

    def builtin_type(self, value):
        """Built-in type function"""
        if isinstance(value, bool):
            return 'boolean'
        elif isinstance(value, int) or isinstance(value, float):
            return 'number'
        elif isinstance(value, str):
            return 'string'
        elif isinstance(value, dict):
            return 'table'
        elif callable(value):
            return 'function'
        elif value is None:
            return 'nil'
        return 'userdata'

    def builtin_tostring(self, value):
        """Built-in tostring function"""
        return self.to_string(value)

    def builtin_tonumber(self, value):
        """Built-in tonumber function"""
        if isinstance(value, (int, float)):
            return value
        s = str(value).strip()
        try:
            if '.' in s:
                return float(s)
            return int(s)
        except:
            return None

    def builtin_assert(self, condition, message=None):
        """Built-in assert function"""
        if not self.is_truthy(condition):
            if message:
                raise RuntimeError(self.to_string(message))
            else:
                raise RuntimeError("Assertion failed")
        return condition

    def str_len(self, s):
        """String length"""
        return len(str(s))

    def str_sub(self, s, i, j=None):
        """String substring"""
        s = str(s)
        i = int(i) - 1  # Lua uses 1-based indexing
        if j is None:
            return s[i:]
        else:
            j = int(j)
            return s[i:j]

    def table_insert(self, table, value):
        """Table insert"""
        if isinstance(table, dict):
            # Find next numeric index
            max_key = 0
            for k in table:
                if isinstance(k, int):
                    max_key = max(max_key, k)
            table[max_key + 1] = value
        return None

    def table_remove(self, table, pos=None):
        """Table remove"""
        if isinstance(table, dict):
            if pos is None:
                pos = len(table)
            else:
                pos = int(pos)
            if pos in table:
                value = table[pos]
                del table[pos]
                return value
        return None

    def to_string(self, value):
        """Convert value to string"""
        if value is None:
            return 'nil'
        elif isinstance(value, bool):
            return 'true' if value else 'false'
        elif isinstance(value, float):
            if value == int(value):
                return str(int(value))
            return str(value)
        elif isinstance(value, dict):
            return 'table'
        elif callable(value):
            return 'function'
        return str(value)

    def get_value(self, name):
        """Get variable value"""
        # Check locals first (in reverse order of stack)
        for scope in reversed(self.locals_stack):
            if name in scope:
                return scope[name]
        # Then globals
        if name in self.globals:
            return self.globals[name]
        raise RuntimeError(f"Undefined variable: {name}")

    def set_value(self, name, value):
        """Set variable value"""
        # Check if variable exists in locals
        for scope in reversed(self.locals_stack):
            if name in scope:
                scope[name] = value
                return
        # Otherwise set in globals
        self.globals[name] = value

    def execute(self, statements):
        """Execute a list of statements"""
        for stmt in statements:
            if self.should_return or self.should_break:
                break
            self.execute_statement(stmt)

    def execute_statement(self, stmt):
        """Execute a single statement"""
        if not stmt:
            return

        cmd = stmt[0]

        if cmd == 'expr_stmt':
            self.eval_expr(stmt[1])

        elif cmd == 'assign':
            value = self.eval_expr(stmt[2])
            self.assign_expr(stmt[1], value)

        elif cmd == 'local':
            var = stmt[1]
            value = self.eval_expr(stmt[2]) if stmt[2] else None
            self.locals_stack[-1][var] = value

        elif cmd == 'if':
            cond = self.eval_expr(stmt[1])
            if self.is_truthy(cond):
                self.execute(stmt[2])
            else:
                self.execute(stmt[3])

        elif cmd == 'for':
            var = stmt[1]
            start = int(self.eval_expr(stmt[2]))
            end = int(self.eval_expr(stmt[3]))
            step = int(self.eval_expr(stmt[4])) if stmt[4] else 1
            body = stmt[5]

            # Create new local scope for loop variable
            self.locals_stack.append({})
            try:
                if step > 0:
                    i = start
                    while i <= end:
                        self.locals_stack[-1][var] = i
                        self.execute(body)
                        if self.should_break:
                            self.should_break = False
                            break
                        if self.should_return:
                            break
                        i += step
                else:
                    i = start
                    while i >= end:
                        self.locals_stack[-1][var] = i
                        self.execute(body)
                        if self.should_break:
                            self.should_break = False
                            break
                        if self.should_return:
                            break
                        i += step
            finally:
                self.locals_stack.pop()

        elif cmd == 'while':
            cond = stmt[1]
            body = stmt[2]
            while self.is_truthy(self.eval_expr(cond)):
                self.execute(body)
                if self.should_break:
                    self.should_break = False
                    break
                if self.should_return:
                    break

        elif cmd == 'function_def':
            name = stmt[1]
            params = stmt[2]
            body = stmt[3]
            func = self.create_function(params, body)
            self.set_value(name, func)

        elif cmd == 'return':
            values = [self.eval_expr(v) for v in stmt[1]]
            self.return_value = values[0] if values else None
            self.should_return = True

        elif cmd == 'break':
            self.should_break = True

    def assign_expr(self, expr, value):
        """Assign value to an expression"""
        if expr[0] == 'var':
            self.set_value(expr[1], value)
        elif expr[0] == 'index':
            table = self.eval_expr(expr[1])
            index = self.eval_expr(expr[2])
            if isinstance(table, dict):
                table[self.to_key(index)] = value
        elif expr[0] == 'field':
            table = self.eval_expr(expr[1])
            field = expr[2]
            if isinstance(table, dict):
                table[field] = value

    def to_key(self, value):
        """Convert value to table key"""
        if isinstance(value, (int, float)):
            if value == int(value):
                return int(value)
            return value
        return str(value)

    def eval_expr(self, expr):
        """Evaluate an expression"""
        if not expr:
            return None

        cmd = expr[0]

        if cmd == 'number':
            return expr[1]

        elif cmd == 'string':
            return expr[1]

        elif cmd == 'bool':
            return expr[1]

        elif cmd == 'nil':
            return None

        elif cmd == 'var':
            return self.get_value(expr[1])

        elif cmd == 'table':
            table = {}
            array_index = 1
            for elem in expr[1]:
                if elem[0] == 'kvpair':
                    table[elem[1]] = self.eval_expr(elem[2])
                else:  # arrayelem
                    table[array_index] = self.eval_expr(elem[1])
                    array_index += 1
            return table

        elif cmd == 'index':
            table = self.eval_expr(expr[1])
            index = self.eval_expr(expr[2])
            if isinstance(table, dict):
                key = self.to_key(index)
                return table.get(key)
            elif isinstance(table, (list, str)):
                idx = int(index) - 1  # Lua uses 1-based indexing
                try:
                    return table[idx]
                except:
                    return None
            return None

        elif cmd == 'field':
            table = self.eval_expr(expr[1])
            field = expr[2]
            if isinstance(table, dict):
                return table.get(field)
            return None

        elif cmd == 'call':
            func = self.eval_expr(expr[1])
            args = [self.eval_expr(arg) for arg in expr[2]]
            if callable(func):
                return func(*args)
            raise RuntimeError(f"Attempt to call non-function: {func}")

        elif cmd == 'function_expr':
            return self.create_function(expr[1], expr[2])

        elif cmd == '+':
            left = self.eval_expr(expr[1])
            right = self.eval_expr(expr[2])
            return left + right

        elif cmd == '-':
            if len(expr) == 2:  # Unary minus
                return -self.eval_expr(expr[1])
            else:
                left = self.eval_expr(expr[1])
                right = self.eval_expr(expr[2])
                return left - right

        elif cmd == '*':
            left = self.eval_expr(expr[1])
            right = self.eval_expr(expr[2])
            return left * right

        elif cmd == '/':
            left = self.eval_expr(expr[1])
            right = self.eval_expr(expr[2])
            return left / right

        elif cmd == '%':
            left = self.eval_expr(expr[1])
            right = self.eval_expr(expr[2])
            return left % right

        elif cmd == '^':
            left = self.eval_expr(expr[1])
            right = self.eval_expr(expr[2])
            return left ** right

        elif cmd == 'concat':
            left = self.eval_expr(expr[1])
            right = self.eval_expr(expr[2])
            return self.to_string(left) + self.to_string(right)

        elif cmd == 'cmp':
            op = expr[1]
            left = self.eval_expr(expr[2])
            right = self.eval_expr(expr[3])

            if op == '==':
                return left == right
            elif op == '~=':
                return left != right
            elif op == '<':
                return left < right
            elif op == '>':
                return left > right
            elif op == '<=':
                return left <= right
            elif op == '>=':
                return left >= right

        elif cmd == 'and':
            left = self.eval_expr(expr[1])
            if self.is_truthy(left):
                return self.eval_expr(expr[2])
            return left

        elif cmd == 'or':
            left = self.eval_expr(expr[1])
            if self.is_truthy(left):
                return left
            return self.eval_expr(expr[2])

        elif cmd == 'not':
            value = self.eval_expr(expr[1])
            return not self.is_truthy(value)

        return None

    def is_truthy(self, value):
        """Check if value is truthy in Lua"""
        if value is None or value is False:
            return False
        return True

    def create_function(self, params, body):
        """Create a function"""
        def func(*args):
            # Create new scope
            self.locals_stack.append({})
            try:
                # Bind parameters
                for i, param in enumerate(params):
                    self.locals_stack[-1][param] = args[i] if i < len(args) else None

                # Execute body
                self.should_return = False
                self.return_value = None
                self.execute(body)
                result = self.return_value
                self.should_return = False
                return result
            finally:
                self.locals_stack.pop()

        return func

def execute_lua(code, script_path=None, script_args=None):
    """Execute Lua code"""
    try:
        lexer = Lexer(code)
        tokens = lexer.tokenize()
        parser = Parser(tokens)
        ast = parser.parse()
        interp = Interpreter(script_path=script_path, script_args=script_args)
        interp.execute(ast)
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        return 1
    return 0

def main():
    """Main entry point"""
    import argparse

    parser = argparse.ArgumentParser(prog=sys.argv[0], add_help=False)
    parser.add_argument('-v', '--version', action='store_true', help='Show version')
    parser.add_argument('-e', type=str, help='Execute Lua code')
    parser.add_argument('-i', '--interactive', action='store_true', help='Interactive mode')
    parser.add_argument('-l', type=str, help='Load library')
    parser.add_argument('--', dest='stop_options', action='store_true', help='Stop processing options')
    parser.add_argument('-', dest='read_stdin', action='store_true', help='Read from stdin')
    parser.add_argument('-h', action='store_true', help='Show help')
    parser.add_argument('-E', action='store_true', help='Ignore environment variables')
    parser.add_argument('script', nargs='?', default=None, help='Script file to execute')
    parser.add_argument('args', nargs='*', help='Arguments to pass to script')

    args = parser.parse_args()

    if args.h:
        print(f"usage: {sys.argv[0]} [options]... [script [args]...].")
        print("Available options are:")
        print("  -e chunk  Execute string 'chunk'.")
        print("  -l name   Require library 'name'.")
        print("  -b ...    Save or list bytecode.")
        print("  -j cmd    Perform LuaJIT control command.")
        print("  -O[opt]   Control LuaJIT optimizations.")
        print("  -i        Enter interactive mode after executing 'script'.")
        print("  -v        Show version information.")
        print("  -E        Ignore environment variables.")
        print("  --        Stop handling options.")
        print("  -         Execute stdin and stop handling options.")
        return 0

    if args.version:
        print(f"{LUAJIT_VERSION} -- Copyright (C) 2005-2026 Mike Pall. https://luajit.org/")
        return 0

    if args.read_stdin or args.script == '-':
        code = sys.stdin.read()
        return execute_lua(code)

    if args.e:
        result = execute_lua(args.e)
        if result != 0:
            return result

    if args.script:
        try:
            with open(args.script, 'r') as f:
                code = f.read()
            return execute_lua(code, script_path=args.script, script_args=args.args)
        except FileNotFoundError:
            print(f"Error: cannot open file '{args.script}'", file=sys.stderr)
            return 1

    if args.interactive or (not args.e and not args.script):
        # Interactive mode
        interp = Interpreter()
        version_printed = False
        while True:
            try:
                if not version_printed:
                    print(f"{LUAJIT_VERSION} -- Copyright (C) 2005-2026 Mike Pall. https://luajit.org/")
                    print(f"JIT: ON SSE3 SSE4.1 BMI2 fold cse dce fwd dse narrow loop abc sink fuse")
                    version_printed = True

                line = input('> ')
                if line:
                    try:
                        lexer = Lexer(line)
                        tokens = lexer.tokenize()
                        parser = Parser(tokens)
                        ast = parser.parse()
                        interp.execute(ast)
                    except Exception as e:
                        print(f"Error: {e}")
            except EOFError:
                break
            except KeyboardInterrupt:
                print()
                continue

    return 0

if __name__ == '__main__':
    sys.exit(main())
